css:
.fx-bgt{width:min(520px,100%)}
.fx-bgt .top{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:.8em}
.fx-bgt .val{font:700 2.6em/1 var(--font-heading);color:var(--primary)}
.fx-bgt .val small{font-size:.4em;opacity:.6;margin-right:.2em;font-family:var(--font-body)}
.fx-bgt input{-webkit-appearance:none;appearance:none;width:100%;height:.6em;border-radius:99px;outline:none;background:linear-gradient(90deg,var(--accent) var(--p,30%),var(--border) var(--p,30%));cursor:pointer}
.fx-bgt input::-webkit-slider-thumb{-webkit-appearance:none;width:1.7em;height:1.7em;border-radius:50%;background:var(--surface);border:3px solid var(--primary);box-shadow:0 2px 8px color-mix(in srgb,#000 25%,transparent)}
.fx-bgt input::-moz-range-thumb{width:1.4em;height:1.4em;border-radius:50%;background:var(--surface);border:3px solid var(--primary)}
.fx-bgt input:focus-visible{outline:2px solid var(--primary);outline-offset:6px}
.fx-bgt .ticks{display:flex;justify-content:space-between;font-size:.8em;opacity:.6;margin-top:.6em}
.fx-bgt .tier{margin-top:1.2em;padding:1em 1.1em;border-radius:var(--radius);background:color-mix(in srgb,var(--primary) 8%,var(--surface));border-left:4px solid var(--accent)}
.fx-bgt .tier b{display:block;margin-bottom:.2em}

js:
(function(){var i=document.getElementById('fx-bgt-i'),v=document.getElementById('fx-bgt-v'),t=document.getElementById('fx-bgt-t');
var tiers=[[40000,'Refresh','Paint, flooring touch-ups, lighting and fixtures for one or two rooms.'],[100000,'Room makeover','Kitchen or bathroom overhaul with new cabinetry and wet works.'],[200000,'Full home','Whole-unit renovation with new layout, electrical and carpentry.'],[1e9,'Premium rebuild','Structural changes, custom joinery and designer-grade finishes.']];
function up(){var n=+i.value;v.textContent=n.toLocaleString('en-US');i.style.setProperty('--p',((n-i.min)/(i.max-i.min)*100)+'%');
var k=tiers.find(function(x){return n<x[0]});t.innerHTML='<b>'+k[1]+'</b>'+k[2]}
i.addEventListener('input',up);up()})();
